import{_ as o,a0 as l,w as p,s as r,ao as d,I as n,x as a,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"PyCaret：機器學習模型開發變得簡單 | LCTT x X-CMD","titleTemplate":false,"description":"PyCaret：機器學習模型開發變得簡單 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PyCaret：機器學習模型開發變得簡單 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PyCaret：機器學習模型開發變得簡單 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220509 PyCaret- Machine Learning Model Development Made Easy","title":"PyCaret：機器學習模型開發變得簡單","tag":"202205","desc":""},"relativePath":"202205/20220509 PyCaret- Machine Learning Model Development Made Easy.md","filePath":"[post].md"}'),h={name:"202205/20220509 PyCaret- Machine Learning Model Development Made Easy.md"};function c(g,e,u,m,k,b){const t=l("Link");return p(),r("div",null,[e[15]||(e[15]=d(`<h1 id="pycaret-機器學習模型開發變得簡單" tabindex="-1">PyCaret：機器學習模型開發變得簡單 <a class="header-anchor" href="#pycaret-機器學習模型開發變得簡單" aria-label="Permalink to “PyCaret：機器學習模型開發變得簡單”">​</a></h1><blockquote><p>在當今快節奏的數字世界中，機構們使用低代碼/無代碼（LC/NC）應用來快速構建新的信息系統。本文將介紹 PyCaret，這是一個用 Python 編寫的低代碼機器學習庫。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Featured-image-of-pycaret-696x477.jpg" alt="Featured-image-of-pycaret"></p><p>PyCaret 是 R 編程語言中 Caret（<ruby>分類和迴歸訓練<rt>Classification And REgression Training</rt></ruby>的縮寫）包的 Python 版本，具有許多優點。</p><ul><li><strong>提高工作效率：</strong> PyCaret 是一個低代碼庫，可讓你提高工作效率。由於花費更少的時間進行編碼，你和你的團隊現在可以專注於業務問題。</li><li><strong>易於使用：</strong> 這個簡單易用的機器學習庫將幫助你以更少的代碼行執行端到端的機器學習實驗。</li><li><strong>可用於商業：</strong> PyCaret 是一個可用於商業的解決方案。它允許你從選擇的 notebook 環境中快速有效地進行原型設計。</li></ul><p>你可以在 Python 中創建一個虛擬環境並執行以下命令來安裝 PyCaret 完整版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install pycaret [full]</span></span></code></pre></div><p>機器學習從業者可以使用 PyCaret 進行分類、迴歸、聚類、異常檢測、自然語言處理、關聯規則挖掘和時間序列分析。</p><h3 id="使用-pycaret-構建分類模型" tabindex="-1">使用 PyCaret 構建分類模型 <a class="header-anchor" href="#使用-pycaret-構建分類模型" aria-label="Permalink to “使用 PyCaret 構建分類模型”">​</a></h3><p>本文通過從 PyCaret 的數據倉庫中獲取 Iris 數據集來解釋使用 PyCaret 構建分類模型。</p><p>我們將使用 Google Colab 環境使事情變得簡單，並按照下面提到的步驟進行操作。</p><h4 id="步驟-1" tabindex="-1">步驟 1 <a class="header-anchor" href="#步驟-1" aria-label="Permalink to “步驟 1”">​</a></h4><p>首先，通過給出以下命令安裝 PyCaret：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install pycaret</span></span></code></pre></div><h4 id="步驟-2" tabindex="-1">步驟 2 <a class="header-anchor" href="#步驟-2" aria-label="Permalink to “步驟 2”">​</a></h4><p>接下來，加載數據集，如圖 2 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-1-loading-the-dataset.jpg" alt="Loading the data set"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from pycaret.datasets import get_data</span></span>
<span class="line"><span>dataset = get_data(&#39;iris&#39;) </span></span>
<span class="line"><span>（或者）</span></span>
<span class="line"><span>import pandas as pd </span></span>
<span class="line"><span>dataset = pd.read_csv(&#39;/path_to_data/file.csv&#39;)</span></span></code></pre></div><h4 id="步驟-3" tabindex="-1">步驟 3 <a class="header-anchor" href="#步驟-3" aria-label="Permalink to “步驟 3”">​</a></h4><p>現在設置 PyCaret 環境，如圖 2 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-2-PyCaret-Environment-Setup.jpg" alt="PyCaret environment setup"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from pycaret.classification import *</span></span>
<span class="line"><span>clf1 = setup(data=dataset, target = ‘species’)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-3-PyCaret-Environment-Setup-Result.jpg" alt="PyCaret environment setup result"></p><p>使用 PyCaret 構建任何類型的模型，環境設置是最重要的一步。默認情況下，<code>setup()</code> 函數接受參數 <code>data</code>（Pandas 數據幀）和 <code>target</code>（指向數據集中的類標籤變量）。<code>setup()</code> 函數的結果如圖 3 所示。 <code>setup()</code> 函數默認將 70% 的數據拆分為訓練集，30% 作為測試集，並進行數據預處理，如圖 3 所示。</p><h4 id="步驟-4" tabindex="-1">步驟 4 <a class="header-anchor" href="#步驟-4" aria-label="Permalink to “步驟 4”">​</a></h4><p>接下來，找到最佳模型，如圖 4 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-4-Finding-the-best-model.jpg" alt="Finding the best model"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>best = compare_models()</span></span></code></pre></div><p>默認情況下，<code>compare_models()</code> 應用十倍交叉驗證，並針對具有較少訓練時間的不同分類器計算不同的性能指標，如準確度、AUC、召回率、精度、F1 分數、Kappa 和 MCC，如圖 4 所示。通過將 <code>tubro=True</code> 傳遞給 <code>compare_models()</code> 函數，我們可以嘗試所有分類器。</p><h4 id="步驟-5" tabindex="-1">步驟 5 <a class="header-anchor" href="#步驟-5" aria-label="Permalink to “步驟 5”">​</a></h4><p>現在創建模型，如圖 5 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-5-Creating-the-model.jpg" alt="Creating the model"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lda_model=create_model (‘lda’)</span></span></code></pre></div><p>線性判別分析分類器表現良好，如圖 4 所示。因此，通過將 <code>lda</code> 傳遞給 <code>create_model()</code> 函數，我們可以擬合模型。</p><h4 id="步驟-6" tabindex="-1">步驟 6 <a class="header-anchor" href="#步驟-6" aria-label="Permalink to “步驟 6”">​</a></h4><p>下一步是微調模型，如圖 6 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-6-Tuning-the-model.jpg" alt="Tuning the model"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tuned_lda=tune_model(lda_model)</span></span></code></pre></div><p>超參數的調整可以提高模型的準確性。<code>tune_model()</code> 函數將線性判別分析模型的精度從 0.9818 提高到 0.9909，如圖 7 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-7Tuned-model-details.jpg" alt="Tuned model details"></p><h4 id="步驟-7" tabindex="-1">步驟 7 <a class="header-anchor" href="#步驟-7" aria-label="Permalink to “步驟 7”">​</a></h4><p>下一步是進行預測，如圖 8 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-8-Predictions-using-tuned-model.jpg" alt="Predictions using the tuned model"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>predictions=predict_model(tuned_lda)</span></span></code></pre></div><p><code>predict_model()</code> 函數用於對測試數據中存在的樣本進行預測。</p><h4 id="步驟-8" tabindex="-1">步驟 8 <a class="header-anchor" href="#步驟-8" aria-label="Permalink to “步驟 8”">​</a></h4><p>現在繪製模型性能，如圖 9 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-9-Evaluating-and-ploting-the-model-performance-Confusion-Matrix.jpg" alt="Evaluating and plotting the model performance — confusion matrix"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>evaluate_model(tuned_lda)</span></span></code></pre></div><p><code>evaluate_model()</code> 函數用於以最小的努力開發不同的性能指標。你可以嘗試它們並查看輸出。</p><hr>`,51)),n("p",null,[e[1]||(e[1]=a("via: ",-1)),s(t,{href:"https://www.opensourceforu.com/2022/05/pycaret-machine-learning-model-development-made-easy/"},{default:i(()=>[...e[0]||(e[0]=[a("https://www.opensourceforu.com/2022/05/pycaret-machine-learning-model-development-made-easy/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=a("作者：",-1)),s(t,{href:"https://www.opensourceforu.com/author/s-ratan/"},{default:i(()=>[...e[2]||(e[2]=[a("S Ratan Kumar",-1)])]),_:1}),e[7]||(e[7]=a(" 選題：",-1)),s(t,{href:"https://github.com/lkxed"},{default:i(()=>[...e[3]||(e[3]=[a("lkxed",-1)])]),_:1}),e[8]||(e[8]=a(" 譯者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[a("geekpi",-1)])]),_:1}),e[9]||(e[9]=a(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[a("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=a("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[a("LCTT",-1)])]),_:1}),e[13]||(e[13]=a(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[a("Linux中國",-1)])]),_:1}),e[14]||(e[14]=a(" 榮譽推出",-1))])])}const w=o(h,[["render",c]]);export{C as __pageData,w as default};
